public class Main {
    static int findPeakElement(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            long left = i > 0 ? nums[i - 1] : Long.MIN_VALUE;
            long right = i < n - 1 ? nums[i + 1] : Long.MIN_VALUE;
            if (nums[i] > left && nums[i] > right) return i;   // check every index directly
        }
        return -1;
    }
}

