def find_peak_element(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[mid + 1]:
            hi = mid                    # mid could be the peak, keep it in range
        else:
            lo = mid + 1                # rising, a peak is guaranteed to the right
    return lo

